bool handleUdpDiag(const uint8_t* data,size_t len,IPAddress remote,uint16_t port){
 if(len<4||memcmp(data,"KXDG",4))return false;
 if(len!=8)return true;if(data[4]!=1||data[5]<1||data[5]>kUdpDiagSeries||data[7]!=kUdpDiagPackets){if(data[5]>=1&&data[5]<=kUdpDiagSeries)++udpDiag[data[5]-1].invalid;return true;}
 UdpDiagResult& x=udpDiag[data[5]-1];const uint8_t seq=data[6];x.remote=remote;x.port=port;if(seq>=kUdpDiagPackets){++x.invalid;return true;}const uint32_t bit=uint32_t(1)<<seq,now=micros();if(x.bitmap&bit){++x.duplicates;return true;}x.bitmap|=bit;++x.received;if(!x.firstUs)x.firstUs=now;if(x.lastUs){uint32_t gap=now-x.lastUs;if(gap>x.maxInterUs)x.maxInterUs=gap;}x.lastUs=now;return true;
}
void considerIpToTp(CemiFrame& cemi,IPAddress remote){
 ++routeReceived;char src[16],dst[16];formatPa(cemi.sourceAddress(),src,sizeof(src));
 if(cemi.addressType()==GroupAddress)formatGroup(cemi.destinationAddress(),dst,sizeof(dst));else formatPa(cemi.destinationAddress(),dst,sizeof(dst));
 if(!ipTpEnabled){++routeFiltered;routeDecision("recu puis filtre passif: %s -> %s hop=%u",src,dst,cemi.hopCount());return;}
 if(cemi.addressType()!=GroupAddress||cemi.destinationAddress()!=kTestGroup||cemi.apdu().type()!=GroupValueWrite){++routeFiltered;routeDecision("filtre hors perimetre: %s -> %s apci=%03X",src,dst,unsigned(cemi.apdu().type()));return;}
 if(remote==IPAddress(192,168,50,60)){++routeFiltered;routeDecision("filtre Siemens 192.0.2.60: %s -> %s",src,dst);return;}
 if(!cemi.hopCount()||cemi.sourceAddress()==kPrototypeAddress||cemi.sourceAddress()==0xFFFF){++routeFiltered;routeDecision("filtre hop/source invalide: %s -> %s hop=%u",src,dst,cemi.hopCount());return;}
 if(routeCount==kRouteQueueSize){++routeFiltered;routeDecision("filtre file pleine: %s -> %s",src,dst);return;}
 CemiFrame routed(cemi);routed.ack(AckDontCare);routed.hopCount(cemi.hopCount()-1);TpFrame tp(routed);
 if(tp.size()>kRouteTpMax){++routeFiltered;routeDecision("filtre trame TP trop longue: %s -> %s",src,dst);return;}
 uint8_t tail=(routeHead+routeCount)%kRouteQueueSize;RouteQueueEntry& q=routeQueue[tail];q={};q.queuedMs=millis();q.source=cemi.sourceAddress();q.destination=cemi.destinationAddress();q.ipHop=cemi.hopCount();q.tpHop=routed.hopCount();q.tpLen=tp.size();memcpy(q.tp,tp.data(),q.tpLen);++routeCount;++routeQueued;routeDecision("mis en file: %s -> %s hop IP=%u TP=%u",src,dst,q.ipHop,q.tpHop);
}
void processIpDatagram(uint8_t* data,size_t len,IPAddress remote,uint16_t port){
 ++ipDatagrams;
 if(handleUdpDiag(data,len,remote,port))return;
 if(len<6||data[0]!=6||data[1]!=0x10){++ipErrors;return;}
 const uint16_t service=(uint16_t(data[2])<<8)|data[3],declared=(uint16_t(data[4])<<8)|data[5];
 if(declared!=len){++ipErrors;return;}if(service!=RoutingIndication){ipLastIgnoredService=service;++ipIgnored;return;}
 const size_t cemiLen=len-6;if(cemiLen<10){++ipErrors;return;}uint8_t* cemiData=data+6;const size_t add=cemiData[1];
 if(add+10>cemiLen){++ipErrors;return;}const size_t expected=add+size_t(cemiData[add+8])+10;if(expected!=cemiLen){++ipErrors;return;}
 KnxIpRoutingIndication indication(data,len);CemiFrame& cemi=indication.frame();if(!cemi.valid()||cemi.messageCode()!=L_data_ind){++ipErrors;return;}
 ++ipTelegrams;addIpLog(remote,port,cemi,cemiData,cemiLen);considerIpToTp(cemi,remote);
 char src[16],dst[16];formatPa(cemi.sourceAddress(),src,sizeof(src));if(cemi.addressType()==GroupAddress)formatGroup(cemi.destinationAddress(),dst,sizeof(dst));else formatPa(cemi.destinationAddress(),dst,sizeof(dst));
 Serial.printf("[KNX-IP RX #%lu] %s:%u %s -> %s (%s) %s hop=%u; mode IP->TP=%s\n",ipTelegrams,remote.toString().c_str(),port,src,dst,cemi.addressType()==GroupAddress?"groupe":"individuelle",apciName(cemi.apdu().type()),cemi.hopCount(),ipTpEnabled?"actif borne":"passif");
}
void disableIpToTp(const char* reason){ipTpEnabled=false;siemensDisconnectedConfirmed=false;clearRouteQueue();writeUart(0x05);diag=Diag::BusMonitor;frameLen=0;ipTpPhase=IpTpPhase::Passive;routeDecision("mode passif restaure: %s",reason);}
