void startDiagnostic(){diag=Diag::Running;diagStart=millis();lastProbe=diagStart-config.probeMs;attempts=0;frameLen=0;setText(lastDiagnostic,sizeof(lastDiagnostic),"Diagnostic NCN5130 en cours");setText(lastError,sizeof(lastError),"Aucune");Serial.println(F("[NANOBCU] Diagnostic local demarre"));}
void startCleanDiagnostic(){diag=Diag::Idle;resetDiagnosticLogs();configureKnxUart(false);delay(5);startDiagnostic();}
